-- ─────────────────────────────────────────────────────────────────────────────
-- vr_measures / vr_measure_issues / vr_positions — Utah 2025GS committee-only measures
-- ─────────────────────────────────────────────────────────────────────────────
-- WHAT THIS ADDS. 76 Utah bills that until now had no measure row at all,
-- with 81 reviewed issue mappings and 708 committee positions across
-- 100 standing-committee actions. Every one of these bills was already in the
-- committee ingest's refusal bucket for 2025GS: a CONTESTED pass-out-favorably vote,
-- confirmed against the published minutes PDF, with every voting name resolved through
-- the reviewed printed-name map — refused only because nobody had reviewed an issue
-- mapping for the parent bill. Wave 4 read the enrolled text and reviewed them.
--
-- WHERE THE MAPPINGS CAME FROM. db/vr-utah-committee-bills-2025GS.json, one entry per
-- bill, each carrying a direction, a weight, exactly one primary key and prose saying
-- what in the text supports it. 97 of the 173 bills in the bucket are REFUSED in the
-- same file, in writing. No issue key was added to the vocabulary for this pass.
--
-- NO FLOOR VOTES. These measures carry no vr_rollcalls row. A bill reaches this file
-- precisely because it has no admitted floor roll for 2025GS — its floor votes were
-- near-unanimous under the shipped 10%-minority bar, or it never reached a floor vote,
-- or it died in the second chamber. No floor action code was widened and no margin bar
-- was lowered to manufacture one. The consequence is stated rather than hidden:
-- 708 of the 708 positions are the member's ONLY act on that bill and all of them
-- count, because there is no floor vote on these measures for stance-helpers to
-- supersede them with (0 are superseded).
--
-- ACTION TYPE AND WEIGHT ARE UNCHANGED. 'committee_vote' at 0.60 in stance-helpers'
-- act table, printing as "Committee vote", exactly as 20261004000000 wrote it. This
-- file changes no weight, no label, no floor and no threshold.
--
-- THE TIME OF DAY IS NOT KNOWN. The minutes state the meeting's date and do not
-- timestamp the motion, so acted_at is that date at midnight Mountain Standard Time.
--
-- SOURCES. Every measure cites its bill page; every position cites the minutes PDF the
-- act was confirmed against. Each measure's external_ids records which document the
-- mapping was read out of — enrolled text, or the last substitute where the bill never
-- enrolled — so a reader can check the mapping against the same file the curator used.
-- Generated by scripts/vr-utah-committee-mapping.mjs --sql --session 2025GS. Idempotent.
-- ─────────────────────────────────────────────────────────────────────────────

-- HB0070 · H.B. 70 · Decommissioned Asset Disposition Amendments
--   mapping read from the enrolled text: https://le.utah.gov/Session/2025/bills/enrolled/HB0070.xml
--   1 issue mapping(s), 1 committee action(s), 6 position(s)
DO $$
DECLARE m_id integer;
BEGIN
  SELECT id INTO m_id FROM vr_measures
   WHERE number = 'H.B. 70' AND chamber = 'utah house'
     AND external_ids->>'utahSession' = '2025GS' LIMIT 1;
  IF m_id IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title,
      short_title, summary, status, source_url, source_label, external_ids)
    VALUES ('bill', NULL, 'utah house', 'H.B. 70', 'Decommissioned Asset Disposition Amendments',
      'Decommissioned Asset Disposition Amendments', 'This bill makes changes to the requirements related to the decommissioning and disposal of electrical generation facilities and equipment by a project entity.', 'enacted',
      'https://le.utah.gov/~2025/bills/static/HB0070.html', 'Utah State Legislature',
      jsonb_build_object('utahSession', '2025GS', 'utahBill', 'HB0070',
        'primeSponsor', 'Rep. Walter, R. Neil', 'floorSponsor', 'Sen. Owens, Derrin R.',
        'mappingReadFrom', 'enrolled', 'mappingTextUrl', 'https://le.utah.gov/Session/2025/bills/enrolled/HB0070.xml',
        'committeeOnly', true))
    RETURNING id INTO m_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM vr_measure_issues
                  WHERE measure_id = m_id AND issue_key = 'energy_production') THEN
    INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary,
      support_meaning, rationale, source_url)
    VALUES (m_id, 'energy_production', 65, true,
      'yea_supports', 'Enrolled text bars a project entity from intentionally preventing the functionality of its existing coal-powered generation facility and requires it to maintain at least one operational coal unit connected to existing interconnection facilities and switchyard equipment so remaining units can be reactivated; the new Utah Energy Council exists to keep those assets generating under a competitively selected operator. A yea keeps thermal generating capacity on the grid.', 'https://le.utah.gov/Session/2025/bills/enrolled/HB0070.xml');
  END IF;
  -- 2025-03-04 · Senate Transportation, Public Utilities, Energy, and Technology Standing Committee · Sen. Millner moved to pass 2nd Substitute H.B. 70 out favorably.
  --   printed tally 5-1-2 (yea-nay-absent); 6 named voter(s) on the PolitiDex roster
