    (m_id, 'kathleen_riebe', 'committee_vote', true, '2025-03-04T00:00:00-07:00'::timestamptz, 'https://le.utah.gov/interim/2025/pdf/00001932.pdf', 'Senate Transportation, Public Utilities, Energy, and Technology Standing Committee · meeting 19924 · Sen. Millner moved to pass 2nd Substitute H.B. 70 out favorably.'),
    (m_id, 'kwan_s12', 'committee_vote', false, '2025-03-04T00:00:00-07:00'::timestamptz, 'https://le.utah.gov/interim/2025/pdf/00001932.pdf', 'Senate Transportation, Public Utilities, Energy, and Technology Standing Committee · meeting 19924 · Sen. Millner moved to pass 2nd Substitute H.B. 70 out favorably.'),
