-- HB0230 · H.B. 230 · Blockchain and Digital Innovation Amendments
--   mapping read from the enrolled text: https://le.utah.gov/Session/2025/bills/enrolled/HB0230.xml
--   1 issue mapping(s), 1 committee action(s), 6 position(s)
DO $$
DECLARE m_id integer;
BEGIN
  SELECT id INTO m_id FROM vr_measures
   WHERE number = 'H.B. 230' AND chamber = 'utah house'
     AND external_ids->>'utahSession' = '2025GS' LIMIT 1;
  IF m_id IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title,
      short_title, summary, status, source_url, source_label, external_ids)
    VALUES ('bill', NULL, 'utah house', 'H.B. 230', 'Blockchain and Digital Innovation Amendments',
      'Blockchain and Digital Innovation Amendments', 'This bill creates authority for the state treasurer to invest public funds in certain digital assets.', 'enacted',
      'https://le.utah.gov/~2025/bills/static/HB0230.html', 'Utah State Legislature',
      jsonb_build_object('utahSession', '2025GS', 'utahBill', 'HB0230',
