   WHERE number = 'H.B. 293' AND chamber = 'utah house'
     AND external_ids->>'utahSession' = '2025GS' LIMIT 1;
  IF m_id IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title,
      short_title, summary, status, source_url, source_label, external_ids)
    VALUES ('bill', NULL, 'utah house', 'H.B. 293', 'Vehicle Sales Tax Amendments',
      'Vehicle Sales Tax Amendments', 'This bill enacts a sales and use tax exemption for sales of motor vehicles in separate transactions.', 'introduced',
      'https://le.utah.gov/~2025/bills/static/HB0293.html', 'Utah State Legislature',
      jsonb_build_object('utahSession', '2025GS', 'utahBill', 'HB0293',
        'primeSponsor', 'Rep. Teuscher, Jordan D.', 'floorSponsor', 'Sen. McCay, Daniel',
        'mappingReadFrom', 'substitute_1', 'mappingTextUrl', 'https://le.utah.gov/Session/2025/bills/introduced/HB0293S01.xml',
        'committeeOnly', true))
    RETURNING id INTO m_id;
