    INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary,
      support_meaning, rationale, source_url)
    VALUES (m_id, 'lower_taxes', 45, true,
      'yea_supports', 'First substitute text exempts the purchase price of the lower priced motor vehicle from sales and use tax when a person buys one vehicle and sells another in separate transactions, and sets out how to claim the exemption. It is a single new tax exemption with no offsetting increase, so the direction is a tax cut and the narrow scope is why the weight sits at the floor.', 'https://le.utah.gov/Session/2025/bills/introduced/HB0293S01.xml');
