DO $$
DECLARE m_id integer;
BEGIN
  SELECT id INTO m_id FROM vr_measures
   WHERE number = 'H.B. 300' AND chamber = 'utah house'
     AND external_ids->>'utahSession' = '2025GS' LIMIT 1;
  IF m_id IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title,
      short_title, summary, status, source_url, source_label, external_ids)
    VALUES ('bill', NULL, 'utah house', 'H.B. 300', 'Amendments to Election Law',
      'Amendments to Election Law', 'This bill amends provisions relating to elections.', 'enacted',
      'https://le.utah.gov/~2025/bills/static/HB0300.html', 'Utah State Legislature',
      jsonb_build_object('utahSession', '2025GS', 'utahBill', 'HB0300',
        'primeSponsor', 'Rep. Burton, Jefferson S.', 'floorSponsor', 'Sen. McKell, Michael K.',
        'mappingReadFrom', 'enrolled', 'mappingTextUrl', 'https://le.utah.gov/Session/2025/bills/enrolled/HB0300.xml',
        'committeeOnly', true))
    RETURNING id INTO m_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM vr_measure_issues
                  WHERE measure_id = m_id AND issue_key = 'voter_id') THEN
    INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary,
      support_meaning, rationale, source_url)
    VALUES (m_id, 'voter_id', 75, true,
      'yea_supports', 'Enrolled text requires a voter returning a mail ballot to provide identifying digits from a state identification document and requires the election officer to verify them before the ballot counts, replacing signature comparison as the sole check. That is an identification requirement attached to casting a ballot.', 'https://le.utah.gov/Session/2025/bills/enrolled/HB0300.xml');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM vr_measure_issues
                  WHERE measure_id = m_id AND issue_key = 'voting_access') THEN
    INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary,
      support_meaning, rationale, source_url)
    VALUES (m_id, 'voting_access', 45, false,
      'yea_opposes', 'A distinct provision of the same enrolled text ends universal mail balloting: beginning with the 2029 cycle a voter must opt in to receive a ballot by mail rather than being sent one automatically. That is a separate operative change from the identification requirement and it narrows how ballots reach voters, which earns its own key.', 'https://le.utah.gov/Session/2025/bills/enrolled/HB0300.xml');
  END IF;
  -- 2025-03-03 · Senate Business and Labor Standing Committee · Sen. Musselman moved to pass 3rd Substitute H.B. 300 out favorably.
