-- HB0413 · H.B. 413 · Child Custody Proceedings Amendments
--   mapping read from the substitute_1 text: https://le.utah.gov/Session/2025/bills/introduced/HB0413S01.xml
--   2 issue mapping(s), 1 committee action(s), 8 position(s)
DO $$
DECLARE m_id integer;
BEGIN
  SELECT id INTO m_id FROM vr_measures
   WHERE number = 'H.B. 413' AND chamber = 'utah house'
     AND external_ids->>'utahSession' = '2025GS' LIMIT 1;
  IF m_id IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title,
      short_title, summary, status, source_url, source_label, external_ids)
    VALUES ('bill', NULL, 'utah house', 'H.B. 413', 'Child Custody Proceedings Amendments',
      'Child Custody Proceedings Amendments', 'This bill addresses situations related to child custody.', 'introduced',
      'https://le.utah.gov/~2025/bills/static/HB0413.html', 'Utah State Legislature',
      jsonb_build_object('utahSession', '2025GS', 'utahBill', 'HB0413',
        'primeSponsor', 'Rep. Kohler, Mike L.', 'floorSponsor', 'Sen. McKell, Michael K.',
        'mappingReadFrom', 'substitute_1', 'mappingTextUrl', 'https://le.utah.gov/Session/2025/bills/introduced/HB0413S01.xml',
        'committeeOnly', true))
    RETURNING id INTO m_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM vr_measure_issues
                  WHERE measure_id = m_id AND issue_key = 'lgbtq_rights') THEN
    INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary,
      support_meaning, rationale, source_url)
    VALUES (m_id, 'lgbtq_rights', 55, true,
      'yea_opposes', 'First substitute text bars a peace officer or caseworker from taking action on the sole or partial basis that a parent asserts the gender or gender identity of the minor child is the same as the child''s biological sex at birth, or does not allow, authorize, accommodate, or support a social or medical transition. The shield is defined by the parent''s refusal to affirm.', 'https://le.utah.gov/Session/2025/bills/introduced/HB0413S01.xml');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM vr_measure_issues
                  WHERE measure_id = m_id AND issue_key = 'cannabis_reform') THEN
    INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary,
      support_meaning, rationale, source_url)
    VALUES (m_id, 'cannabis_reform', 45, false,
      'yea_supports', 'A distinct provision of the same text bars action based solely on the possession or use of cannabis in a medicinal dosage form and forbids a negative inference from a parent''s status as a cannabis establishment, medical cannabis pharmacy, or courier agent. That protects medical cannabis patients and workers from child-welfare consequences and is separate from the gender-identity shield.', 'https://le.utah.gov/Session/2025/bills/introduced/HB0413S01.xml');
  END IF;
  -- 2025-02-24 · House Judiciary Standing Committee · Rep. Auxier moved to pass 1st Substitute H.B. 413 out favorably.
