  IF m_id IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title,
      short_title, summary, status, source_url, source_label, external_ids)
    VALUES ('bill', NULL, 'utah house', 'H.B. 548', 'Genetic Information Amendments',
      'Genetic Information Amendments', 'This bill addresses the use of genetic sequencing tools and the storage of genetic sequencing data.', 'introduced',
      'https://le.utah.gov/~2025/bills/static/HB0548.html', 'Utah State Legislature',
      jsonb_build_object('utahSession', '2025GS', 'utahBill', 'HB0548',
        'primeSponsor', 'Rep. Brooks, Walt', 'floorSponsor', 'Sen. Stevenson, Jerry W.',
