      support_meaning, rationale, source_url)
    VALUES (m_id, 'privacy_rights', 55, true,
      'yea_supports', 'Fourth substitute text bars a medical or genomic research facility from using a genetic sequencer or research software produced or distributed by a foreign adversary, bars storing genetic sequencing data inside a foreign adversary''s boundaries or granting remote access from there without written approval, fines violations per genome, and protects an employee who reports a violation. The protected thing throughout is a person''s genetic data.', 'https://le.utah.gov/Session/2025/bills/introduced/HB0548S04.xml');
